package claude

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	osexec "os/exec"
	"strings"
	"syscall"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/easel/fizeau/internal/modelcatalog"
)

// Fallback only: unpinned runs resolve through model discovery first.
const fallbackDefaultModel = "claude-sonnet-4-6"

// Default size for the per-Execute event channel buffer. Large enough that
// fast tool-call bursts (claude can emit dozens of blocks per turn) do not
// stall the parser, small enough to bound memory in pathological streams.
const defaultEventBuffer = 64

// Default idle/stream timeout when ExecuteRequest leaves IdleTimeout unset.
// Mirrors the wall-clock cap the DDx-side runner used historically; an
// explicit ExecuteRequest.Timeout still wins.
const defaultIdleTimeout = 0 // 0 = no idle cap; rely on Timeout / ctx.

// Runner is the subprocess-backed claude harness. It launches the claude
// CLI in stream-json mode, parses each line into harness Events, and emits
// a final Event when the subprocess exits. On ctx.Done(), the subprocess
// (and any forked children belonging to its process group) is signalled
// SIGTERM and reaped so PTY/tool children don't outlive the request.
type Runner struct {
	// Binary is the absolute path to the claude executable. When empty the
	// runner resolves "claude" via PATH at Execute time.
	Binary string

	// BaseArgs is prepended to the per-request argument list; callers use
	// it to pin a consistent invocation profile (e.g. ["--print", "-p",
	// "--output-format", "stream-json", "--verbose"]).
	BaseArgs []string

	// PromptMode controls how the prompt is delivered to claude:
	//   "stdin" (default) — prompt is piped on stdin
	//   "arg"             — prompt is appended as the final positional argument
	PromptMode string

	// EventBuffer overrides the per-Execute channel buffer size. Zero
	// selects defaultEventBuffer.
	EventBuffer int

	// DiscoveryCache overrides model/reasoning discovery evidence in tests.
	DiscoveryCache *harnesses.ModelDiscoveryCache

	// NativeMode routes Execute through the native Anthropic Messages API
	// (streaming HTTP via internal/provider/anthropic) instead of os/exec'ing
	// `claude --print`. In native mode the runner is metered
	// (actual_cash_spend) and reports IsSubscription=false — distinct from the
	// claude-tui flat-subscription surface.
	NativeMode bool

	// NativeProvider overrides the streaming provider used by the native path.
	// When nil, the runner builds the real metered Anthropic provider via
	// nativeFactory. Tests inject a fake here.
	NativeProvider NativeStreamingProvider

	// nativeFactory builds the native provider when NativeProvider is nil. When
	// nil the default Anthropic provider factory is used. Test-only seam.
	nativeFactory nativeProviderFactory

	// NativeTools is the tool set the native agentic loop may execute. The
	// subprocess path delegates tool execution to the claude CLI; the native
	// Messages API only emits tool_use requests, so the runner executes them
	// against this set and feeds back tool_result. Empty = no tools.
	NativeTools []agentcore.Tool

	// NativeAPIKey / NativeBaseURL configure the real metered Anthropic client
	// when NativeProvider is not injected.
	NativeAPIKey  string
	NativeBaseURL string

	// NativeMaxIterations bounds the native agentic loop. Zero selects
	// defaultNativeMaxIterations.
	NativeMaxIterations int
}

// Info returns identity + capability metadata for this harness.
//
// Path is best-effort: the runner reports Binary if set, otherwise looks
// up "claude" on PATH. Available tracks whether the lookup succeeded so
// callers can show a useful error in `ddx agent list` without invoking
// HealthCheck synchronously.
func (r *Runner) Info() harnesses.HarnessInfo {
	info := harnesses.HarnessInfo{
		Name:                 "claude",
		Type:                 "subprocess",
		IsLocal:              false,
		IsSubscription:       true,
		AutoRoutingEligible:  true,
		ExactPinSupport:      true,
		DefaultModel:         harnesses.ResolveRunnerModel("claude", modelcatalog.SurfaceClaudeCode, "", fallbackDefaultModel).ResolvedModel,
		SupportedPermissions: []string{"safe", "supervised", "unrestricted"},
		SupportedReasoning:   []string{"low", "medium", "high", "xhigh", "max"},
		CostClass:            "medium",
	}
	if r.NativeMode {
		// Native path uses the Anthropic Messages API directly (metered,
		// actual_cash_spend) — there is no flat subscription and no claude
		// binary involved.
		info.Type = "native"
		info.IsSubscription = false
		info.Available = true
		return info
	}
	path := r.Binary
	if path == "" {
		if resolved, err := osexec.LookPath("claude"); err == nil {
			path = resolved
		}
	}
	if path != "" {
		info.Path = path
		info.Available = true
	} else {
		info.Error = "claude binary not found in PATH"
	}
	return info
}

// HealthCheck verifies the claude binary resolves on PATH (or at the
// configured Binary). It does NOT invoke the binary so it stays cheap and
// safe to call from request hot paths. A future extension can probe quota
// state via the cache layer.
func (r *Runner) HealthCheck(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if r.NativeMode {
		// Native mode reaches the metered Anthropic Messages API over HTTP and
		// never os/exec's the claude CLI, so binary presence is irrelevant to
		// health. (Execute likewise branches on NativeMode before resolving the
		// binary.) Credential/provider reachability is validated lazily on the
		// first native turn, not here.
		return nil
	}
	path := r.Binary
	if path == "" {
		resolved, err := osexec.LookPath("claude")
		if err != nil {
			return fmt.Errorf("claude binary not found: %w", err)
		}
		path = resolved
	}
	st, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat claude binary: %w", err)
	}
	if st.IsDir() {
		return fmt.Errorf("claude binary path is a directory: %s", path)
	}
	return nil
}

// Execute runs one resolved request through the claude CLI and emits
// stream-derived events on the returned channel. The channel is closed
// once a final event has been emitted. PTY/orphan children are reaped on
// ctx.Done(). If the CLI rejects stream-json flags (older build), the
// runner falls back to a buffered legacy invocation and emits a single
// text_delta + final from the buffered output.
func (r *Runner) Execute(ctx context.Context, req harnesses.ExecuteRequest) (<-chan harnesses.Event, error) {
	bufSize := r.EventBuffer
	if bufSize <= 0 {
		bufSize = defaultEventBuffer
	}

	// Channel returned to the caller; the goroutine below owns closing it.
	out := make(chan harnesses.Event, bufSize)

	if r.NativeMode {
		// Native path does not os/exec the claude binary at all.
		go r.run(ctx, "", req, out)
		return out, nil
	}

	binary := r.Binary
	if binary == "" {
		resolved, err := osexec.LookPath("claude")
		if err != nil {
			return nil, fmt.Errorf("claude binary not found: %w", err)
		}
		binary = resolved
	}

	go r.run(ctx, binary, req, out)
	return out, nil
}

// run is the per-Execute goroutine: starts claude, streams events, and
// guarantees a final event + channel close on every termination path.
func (r *Runner) run(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event) {
	defer close(out)

	start := time.Now()
	var seq int64

	var (
		agg      *streamAggregate
		exitCode int
		stderr   string
		runErr   error
		status   string
	)

	if r.NativeMode {
		agg, exitCode, stderr, runErr, status = r.runNative(ctx, req, out, &seq)
	} else {
		// First attempt: stream-json invocation.
		agg, exitCode, stderr, runErr, status = r.runStreaming(ctx, binary, req, out, &seq)

		// Fallback path: claude rejected the stream-json flags. Retry with the
		// legacy buffered --print/-p/--output-format=json invocation. We surface
		// the legacy output as a single text_delta so consumers still receive
		// the model's final text.
		if status == "failed" && exitCode == 2 && claudeStreamArgsUnsupported(stderr) {
			// Reset the aggregate so legacy output drives final event.
			agg, exitCode, stderr, runErr, status = r.runLegacy(ctx, binary, req, out, &seq)
		}
	}

	// Emit the final event regardless of outcome so downstream consumers
	// always see a terminator. Errors during emit are non-fatal — the
	// channel close still signals end-of-stream.
	final := harnesses.FinalData{
		Status:     status,
		ExitCode:   exitCode,
		DurationMS: time.Since(start).Milliseconds(),
	}
	reasoningResolution := harnesses.ResolveRunnerReasoningWithCache(r.DiscoveryCache, "claude", req.Reasoning)
	if harnesses.ShouldEmitRunnerReasoningResolution(reasoningResolution) {
		final.Reasoning = &reasoningResolution
	}
	quotaMessage := claudeQuotaMessage(stderr, runErr, agg)
	if quotaMessage != "" {
		markClaudeQuotaExhaustedFromMessage(quotaMessage, time.Now())
	}
	if runErr != nil && status != "success" {
		final.Error = runErr.Error()
	} else if stderr != "" && status != "success" {
		final.Error = trimErrorBlob(stderr)
	}
	if quotaMessage != "" && status != "success" {
		final.Error = "claude quota exhausted: " + trimErrorBlob(quotaMessage)
	}
	if agg != nil {
		final.FinalText = agg.FinalText

package serviceimpl

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// fakeClaudeStreamProvider is a serviceimpl-local test double for
// agentcore.StreamingProvider. It replays scripted turns and records that the
// native claude path drove the Messages API (never os/exec'd claude --print).
type fakeClaudeStreamProvider struct {
	turns       [][]agentcore.StreamDelta
	callCount   int
	gotMessages [][]agentcore.Message
	gotOpts     []agentcore.Options
}

func (f *fakeClaudeStreamProvider) Chat(context.Context, []agentcore.Message, []agentcore.ToolDef, agentcore.Options) (agentcore.Response, error) {
	panic("Chat must not be called: native claude path streams")
}

func (f *fakeClaudeStreamProvider) ChatStream(ctx context.Context, messages []agentcore.Message, _ []agentcore.ToolDef, opts agentcore.Options) (<-chan agentcore.StreamDelta, error) {
	idx := f.callCount
	f.callCount++
	f.gotMessages = append(f.gotMessages, messages)
	f.gotOpts = append(f.gotOpts, opts)
	ch := make(chan agentcore.StreamDelta, 16)
	var deltas []agentcore.StreamDelta
	if idx < len(f.turns) {
		deltas = f.turns[idx]
	}
	go func() {
		defer close(ch)
		for _, d := range deltas {
			select {
			case ch <- d:
			case <-ctx.Done():
				return
			}
		}
	}()
	return ch, nil
}

var _ agentcore.StreamingProvider = (*fakeClaudeStreamProvider)(nil)

// fakeUnrestrictedTool is a mutating (non read-only) agentcore.Tool, so it only
// survives the native permission filter under "unrestricted".
type fakeUnrestrictedTool struct {
	called bool
}

func (t *fakeUnrestrictedTool) Name() string            { return "write" }
func (t *fakeUnrestrictedTool) Description() string     { return "fake mutating tool" }
func (t *fakeUnrestrictedTool) Schema() json.RawMessage { return json.RawMessage(`{"type":"object"}`) }
func (t *fakeUnrestrictedTool) Parallel() bool          { return false }
func (t *fakeUnrestrictedTool) Execute(context.Context, json.RawMessage) (string, error) {
	t.called = true
	return "wrote it", nil
}

// TestClaudeTransportSelection proves requirement 3's default-selection half:
// the FIZEAU_CLAUDE_TRANSPORT knob (default = subprocess) controls whether the
// production claude Runner is built native. Unset / "subprocess" / garbage must
// keep NativeMode=false (byte-for-byte unchanged: still spawns claude --print);
// only an explicit "native" flips it on.
func TestClaudeTransportSelection(t *testing.T) {
	cases := []struct {
		value      string
		set        bool
		wantNative bool
	}{
		{set: false, wantNative: false}, // unset -> default subprocess
		{value: "", set: true, wantNative: false},
		{value: "subprocess", set: true, wantNative: false},
		{value: "garbage", set: true, wantNative: false},
		{value: "native", set: true, wantNative: true},
		{value: "NATIVE", set: true, wantNative: true}, // case-insensitive
		{value: " native ", set: true, wantNative: true},
	}
	for _, tc := range cases {
		if tc.set {
			t.Setenv(claudeTransportEnv, tc.value)
		} else {
			t.Setenv(claudeTransportEnv, "")
		}
		if tc.wantNative {
			// Provide a fake key so native cases don't error on missing credential.
			t.Setenv(anthropicAPIKeyEnv, "sk-ant-test-selection")
		} else {
			t.Setenv(anthropicAPIKeyEnv, "")
		}
		runner, err := newClaudeRunner()
		require.NoError(t, err, "FIZEAU_CLAUDE_TRANSPORT=%q (set=%v)", tc.value, tc.set)
		assert.Equal(t, tc.wantNative, runner.NativeMode,
			"FIZEAU_CLAUDE_TRANSPORT=%q (set=%v)", tc.value, tc.set)
	}
}

// TestClaudeNativeCredentialWiring covers AC1 and AC2:
//   - AC1: native transport + API key set → Runner has NativeMode=true and NativeAPIKey populated.
//   - AC2: native transport + no API key → clear early error naming ANTHROPIC_API_KEY.
func TestClaudeNativeCredentialWiring(t *testing.T) {
	t.Run("key set wires NativeAPIKey", func(t *testing.T) {
		t.Setenv(claudeTransportEnv, "native")
		t.Setenv(anthropicAPIKeyEnv, "sk-ant-wiring-test")
		t.Setenv(anthropicBaseURLEnv, "")

		runner, err := newClaudeRunner()
		require.NoError(t, err)
		require.NotNil(t, runner)
		assert.True(t, runner.NativeMode, "native transport must set NativeMode=true")
		assert.Equal(t, "sk-ant-wiring-test", runner.NativeAPIKey, "NativeAPIKey must be populated from ANTHROPIC_API_KEY")
		assert.Equal(t, "", runner.NativeBaseURL, "NativeBaseURL must be empty when ANTHROPIC_BASE_URL is unset")
	})

	t.Run("base URL wired when set", func(t *testing.T) {
		t.Setenv(claudeTransportEnv, "native")
		t.Setenv(anthropicAPIKeyEnv, "sk-ant-wiring-test")
		t.Setenv(anthropicBaseURLEnv, "https://custom.example.com")

		runner, err := newClaudeRunner()
		require.NoError(t, err)
		require.NotNil(t, runner)
		assert.Equal(t, "https://custom.example.com", runner.NativeBaseURL, "NativeBaseURL must be populated from ANTHROPIC_BASE_URL")
	})

	t.Run("no key produces early error naming ANTHROPIC_API_KEY", func(t *testing.T) {
		t.Setenv(claudeTransportEnv, "native")
		t.Setenv(anthropicAPIKeyEnv, "")

		runner, err := newClaudeRunner()
		require.Error(t, err, "native without API key must fail fast")
		assert.Nil(t, runner)
		assert.Contains(t, err.Error(), "ANTHROPIC_API_KEY",
			"error must name the missing key so operators know what to set")
		assert.Contains(t, err.Error(), "FIZEAU_CLAUDE_TRANSPORT=native",
			"error must mention the transport knob to give context")
	})
}

// TestRunSubprocess_ClaudeNativeTransport_EndToEnd is the key proof: with the
// transport knob = native, a claude Execute driven through the SAME production
// execute infrastructure (RunSubprocess -> runner.Execute -> native loop)
// emits text_delta + tool_call + tool_result + final, records metered cost
// (IsSubscription=false / actual_cash_spend), and spawns NO claude --print
// subprocess.
func TestRunSubprocess_ClaudeNativeTransport_EndToEnd(t *testing.T) {
	t.Setenv(claudeTransportEnv, "native")
	t.Setenv(anthropicAPIKeyEnv, "sk-ant-e2e-test")
	require.True(t, claudeNativeTransportSelected(), "knob must select native")

	tool := &fakeUnrestrictedTool{}
	provider := &fakeClaudeStreamProvider{
		turns: [][]agentcore.StreamDelta{
			// Turn 1: a tool_use request.
			{
				{Model: "claude-sonnet-4-20250514", Usage: &agentcore.TokenUsage{Input: 100}},
				{ToolCallID: "tu_1", ToolCallName: "write"},
				{ToolCallID: "tu_1", ToolCallArgs: `{"path":"x"}`},
				{FinishReason: "tool_use"},
				{Done: true},
			},
			// Turn 2: final text answer; 1M in + 1M out against sonnet-4
			// ($3/$15 per MTok) = $18.00 metered.
			{
				{Content: "done "},
				{Content: "answer."},
				{Usage: &agentcore.TokenUsage{Input: 1_000_000, Output: 1_000_000}, FinishReason: "end_turn"},
				{Done: true},
			},
		},
	}

	// Build the runner the way newClaudeRunner does (native, because the knob is
	// set) and inject the fake streaming provider + an explicit tool set. The
	// Binary points at a nonexistent path: a subprocess invocation would fail,
	// so a "success" final proves no claude --print was ever spawned.
	runner, err := newClaudeRunner()
	require.NoError(t, err, "newClaudeRunner must not error when ANTHROPIC_API_KEY is set")
	require.True(t, runner.NativeMode, "knob=native must build a native Runner")
	runner.NativeProvider = provider
	runner.NativeTools = []agentcore.Tool{tool}
	runner.Binary = "/nonexistent/definitely-not-claude"

	// Native harness reports metered billing, not flat subscription.
	assert.False(t, runner.Info().IsSubscription,
		"native claude transport must be metered (IsSubscription=false)")

	var events []harnesses.Event
	cb := SubprocessCallbacks{
		EmitEvent: func(ev harnesses.Event) bool {
			events = append(events, ev)
			return true
		},
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	RunSubprocess(ctx, SubprocessRequest{
		Prompt:       "do a thing",
		SystemPrompt: "you are a test",
		Permissions:  "unrestricted",
		Reasoning:    "high",
		Decision: ExecuteRunnerDecision{
			Harness: "claude",
			Model:   "claude-sonnet-4-20250514",
		},
		Started: time.Now(),
	}, runner, cb)

	by := map[harnesses.EventType]int{}
	var finalEvents []harnesses.Event
	for _, ev := range events {
		by[ev.Type]++
		if ev.Type == harnesses.EventTypeFinal {
			finalEvents = append(finalEvents, ev)
		}
	}
	assert.GreaterOrEqual(t, by[harnesses.EventTypeTextDelta], 1, "expected text_delta events")
	assert.Equal(t, 1, by[harnesses.EventTypeToolCall], "expected one tool_call")
	assert.Equal(t, 1, by[harnesses.EventTypeToolResult], "expected one tool_result")
	require.Len(t, finalEvents, 1, "expected exactly one final event")

	var final harnesses.FinalData
	require.NoError(t, json.Unmarshal(finalEvents[0].Data, &final))

	assert.True(t, tool.called, "native loop must execute the wired tool")
	require.Equal(t, "success", final.Status, "native run must succeed without spawning claude; error=%q", final.Error)
	assert.Equal(t, "done answer.", final.FinalText)
	// 1M input + 1M output against sonnet-4 ($3/$15 per MTok) ≈ $18.00, plus the
	// small turn-1 priming input. Assert metered cost in the expected band.
	assert.InDelta(t, 18.0, final.CostUSD, 0.01, "metered actual_cash_spend cost from native usage")
	assert.Greater(t, final.CostUSD, 0.0, "metered cost must be > 0 (actual_cash_spend)")
	require.NotNil(t, final.Usage)
	require.NotNil(t, final.Usage.InputTokens)
	assert.GreaterOrEqual(t, *final.Usage.InputTokens, 1_000_000, "native usage must flow to metered final")

	// The provider was driven natively (two streamed turns) and reasoning was
	// mapped onto Options.
	require.Equal(t, 2, provider.callCount, "native path must stream both turns")
	require.NotEmpty(t, provider.gotOpts)
	assert.Equal(t, agentcore.Reasoning("high"), provider.gotOpts[0].Reasoning,
		"req.Reasoning must map onto native Options")
	// No message content may resemble a CLI invocation of claude --print.
	require.NotEmpty(t, provider.gotMessages)
	for _, msgs := range provider.gotMessages {
		for _, m := range msgs {
			assert.NotContains(t, m.Content, "--print")
			assert.NotContains(t, m.Content, "stream-json")
		}
	}

package claude

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/harnesses"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// fakeStreamProvider is a test double for agentcore.StreamingProvider. It
// replays a scripted sequence of StreamDelta turns and records the params it
// was called with so tests can prove the native runner drove the native
// Messages API path (and never os/exec'd `claude --print`).
type fakeStreamProvider struct {
	turns [][]agentcore.StreamDelta // one slice of deltas per ChatStream call

	callCount   int
	gotMessages [][]agentcore.Message
	gotTools    [][]agentcore.ToolDef
	gotOpts     []agentcore.Options
}

// Chat satisfies agentcore.Provider; the native runner only uses ChatStream,
// so this should never be invoked in these tests.
func (f *fakeStreamProvider) Chat(_ context.Context, _ []agentcore.Message, _ []agentcore.ToolDef, _ agentcore.Options) (agentcore.Response, error) {
	panic("fakeStreamProvider.Chat must not be called: native runner streams")
}

func (f *fakeStreamProvider) ChatStream(ctx context.Context, messages []agentcore.Message, tools []agentcore.ToolDef, opts agentcore.Options) (<-chan agentcore.StreamDelta, error) {
	idx := f.callCount
	f.callCount++
	f.gotMessages = append(f.gotMessages, messages)
	f.gotTools = append(f.gotTools, tools)
	f.gotOpts = append(f.gotOpts, opts)

	ch := make(chan agentcore.StreamDelta, 16)
	var deltas []agentcore.StreamDelta
	if idx < len(f.turns) {
		deltas = f.turns[idx]
	}
	go func() {
		defer close(ch)
		for _, d := range deltas {
			select {
			case ch <- d:
			case <-ctx.Done():
				return
			}
		}
	}()
	return ch, nil
}

var _ agentcore.StreamingProvider = (*fakeStreamProvider)(nil)

// fakeTool is a minimal agentcore.Tool that records its invocation and returns
// a canned output. The native runner executes tool_use blocks against the
// wired tool set and feeds back tool_result.
type fakeTool struct {
	name      string
	output    string
	called    bool
	gotParams json.RawMessage
}

func (t *fakeTool) Name() string            { return t.name }
func (t *fakeTool) Description() string     { return "fake tool for tests" }
func (t *fakeTool) Schema() json.RawMessage { return json.RawMessage(`{"type":"object"}`) }
func (t *fakeTool) Parallel() bool          { return false }
func (t *fakeTool) Execute(_ context.Context, params json.RawMessage) (string, error) {
	t.called = true
	t.gotParams = params
	return t.output, nil
}

// eventsByType partitions a drained event slice by EventType.
func eventsByType(evs []harnesses.Event) map[harnesses.EventType][]harnesses.Event {
	out := map[harnesses.EventType][]harnesses.Event{}
	for _, e := range evs {
		out[e.Type] = append(out[e.Type], e)
	}
	return out
}

// TestNativeRunner_ToolUsingTurn proves requirement (a): the native path emits
// text_delta + tool_call + tool_result + final for a tool-using turn, driving
// the streaming provider through an agentic loop.
func TestNativeRunner_ToolUsingTurn(t *testing.T) {
	tool := &fakeTool{name: "search", output: "tool says hello"}

	provider := &fakeStreamProvider{
		turns: [][]agentcore.StreamDelta{
			// Turn 1: a tool_use request (id+name, then args fragments, then stop).
			{
				{Model: "claude-sonnet-4-20250514", Usage: &agentcore.TokenUsage{Input: 100}},
				{ToolCallID: "tu_1", ToolCallName: "search"},
				{ToolCallID: "tu_1", ToolCallArgs: `{"q":`},
				{ToolCallID: "tu_1", ToolCallArgs: `"hi"}`},
				{Usage: &agentcore.TokenUsage{Output: 20}, FinishReason: "tool_use"},
				{Done: true},
			},
			// Turn 2: final text answer (no tool calls -> loop terminates).
			{
				{Content: "Final "},
				{Content: "answer."},
				{Usage: &agentcore.TokenUsage{Input: 130, Output: 8}, FinishReason: "end_turn"},
				{Done: true},
			},
		},
	}

	r := &Runner{
		NativeMode:     true,
		NativeProvider: provider,
		NativeTools:    []agentcore.Tool{tool},
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	out, err := r.Execute(ctx, harnesses.ExecuteRequest{
		Prompt:       "do a thing",
		SystemPrompt: "you are a test",
		Model:        "claude-sonnet-4-20250514",
	})
	require.NoError(t, err)

	evs := drainEvents(t, ctx, out)
	by := eventsByType(evs)

	require.NotEmpty(t, by[harnesses.EventTypeTextDelta], "expected text_delta events")
	require.Len(t, by[harnesses.EventTypeToolCall], 1, "expected one tool_call event")
	require.Len(t, by[harnesses.EventTypeToolResult], 1, "expected one tool_result event")
	require.Len(t, by[harnesses.EventTypeFinal], 1, "expected exactly one final event")

	// tool_call carries the assembled input.
	var tcData harnesses.ToolCallData
	require.NoError(t, json.Unmarshal(by[harnesses.EventTypeToolCall][0].Data, &tcData))
	assert.Equal(t, "search", tcData.Name)
	assert.Equal(t, "tu_1", tcData.ID)
	assert.JSONEq(t, `{"q":"hi"}`, string(tcData.Input))

	// The tool actually ran and its output came back as tool_result.
	assert.True(t, tool.called, "tool should have been executed")
	assert.JSONEq(t, `{"q":"hi"}`, string(tool.gotParams))
	var trData harnesses.ToolResultData
	require.NoError(t, json.Unmarshal(by[harnesses.EventTypeToolResult][0].Data, &trData))
	assert.Equal(t, "tu_1", trData.ID)
	assert.Equal(t, "tool says hello", trData.Output)
	assert.Empty(t, trData.Error)

	// Final event: success + final text.
	var final harnesses.FinalData
	require.NoError(t, json.Unmarshal(by[harnesses.EventTypeFinal][0].Data, &final))
	assert.Equal(t, "success", final.Status)
	assert.Equal(t, "Final answer.", final.FinalText)

	// The provider was driven twice (tool turn + final turn).
	assert.Equal(t, 2, provider.callCount)
}

// TestNativeRunner_NoSubprocessSpawned proves requirement (b): the native path
// never os/exec's the claude binary. We assert this two ways:
//  1. Info().Type is "native" (not "subprocess"), and the runner runs to
//     completion with NO claude binary on PATH and Binary set to a path that
//     does not exist — a subprocess invocation would fail to start.
//  2. The provider received native Message structs (a real conversation), not
//     CLI argv containing "--print"; we inspect every recorded param.
func TestNativeRunner_NoSubprocessSpawned(t *testing.T) {
	provider := &fakeStreamProvider{
		turns: [][]agentcore.StreamDelta{
			{
				{Content: "hello"},
				{Usage: &agentcore.TokenUsage{Input: 10, Output: 3}, FinishReason: "end_turn"},
				{Done: true},
			},
		},
	}
	r := &Runner{
		NativeMode:     true,
		NativeProvider: provider,
		// A binary path that cannot be exec'd. If the runner ever tried to
		// spawn it, Execute/run would surface a failure final event.
		Binary: "/nonexistent/definitely-not-claude",
	}

	// Native harness must not claim to be a subprocess and must be available
	// without any claude binary.
	info := r.Info()
	assert.Equal(t, "native", info.Type)
	assert.True(t, info.Available)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	out, err := r.Execute(ctx, harnesses.ExecuteRequest{Prompt: "hi", Model: "claude-sonnet-4-20250514"})
	require.NoError(t, err)
	evs := drainEvents(t, ctx, out)
	by := eventsByType(evs)

	require.Len(t, by[harnesses.EventTypeFinal], 1)
	var final harnesses.FinalData
	require.NoError(t, json.Unmarshal(by[harnesses.EventTypeFinal][0].Data, &final))
	require.Equal(t, "success", final.Status, "native run must succeed without spawning claude; error=%q", final.Error)

	// No recorded provider param may resemble a CLI invocation of `claude
	// --print ...`. The native path passes native Message structs; assert none
	// of the message content is a CLI flag blob.
	require.NotEmpty(t, provider.gotMessages)
	for _, msgs := range provider.gotMessages {
		for _, m := range msgs {
			assert.NotContains(t, m.Content, "--print",
				"native path must not pass CLI args; got message content %q", m.Content)
			assert.NotContains(t, m.Content, "stream-json")
		}
	}

