	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestBuiltinNewClaudeHonorsTransport(t *testing.T) {
	t.Run("unset default", func(t *testing.T) {
		prev, had := os.LookupEnv("FIZEAU_CLAUDE_TRANSPORT")
		require.NoError(t, os.Unsetenv("FIZEAU_CLAUDE_TRANSPORT"))
		t.Cleanup(func() {
			if had {
				require.NoError(t, os.Setenv("FIZEAU_CLAUDE_TRANSPORT", prev))
				return
			}
			require.NoError(t, os.Unsetenv("FIZEAU_CLAUDE_TRANSPORT"))
		})

		runner, ok := New("claude").(*claudeharness.Runner)
		require.True(t, ok, "New(\"claude\") must return a claude runner")
		assert.False(t, runner.NativeMode, "unset transport must keep subprocess mode")
	})

	t.Run("native", func(t *testing.T) {
		t.Setenv("FIZEAU_CLAUDE_TRANSPORT", "native")

		runner, ok := New("claude").(*claudeharness.Runner)
		require.True(t, ok, "New(\"claude\") must return a claude runner")
		assert.True(t, runner.NativeMode, "native transport must set NativeMode=true")
	})
}

